def choose_move(observation):
    # Defensive defaults
    x = observation.get("self_x", 0) if isinstance(observation, dict) else 0
    y = observation.get("self_y", 0) if isinstance(observation, dict) else 0

    # Prefer to stay near center if available
    width = observation.get("width", 0) if isinstance(observation, dict) else 0
    height = observation.get("height", 0) if isinstance(observation, dict) else 0

    # Compute target to stay away from walls when dimensions known
    dx = 0
    dy = 0

    if width:
        cx = width // 2
        if x < cx:
            dx = 1
        elif x > cx:
            dx = -1
        else:
            dx = 0

    if height:
        cy = height // 2
        if y < cy:
            dy = 1
        elif y > cy:
            dy = -1
        else:
            dy = 0

    # Defensive adjustment based on known danger/targets
    # Try to move away from nearest detected enemy if present
    enemies = observation.get("enemies", []) if isinstance(observation, dict) else []
    if enemies:
        # pick closest enemy
        best = None
        best_dist = float("inf")
        for e in enemies:
            ex = e.get("x", x)
            ey = e.get("y", y)
            dist = (ex - x) ** 2 + (ey - y) ** 2
            if dist < best_dist:
                best_dist = dist
                best = (ex, ey)
        if best is not None and best_dist <= 4:
            ex, ey = best
            if ex > x:
                dx = -1
            elif ex < x:
                dx = 1
            if ey > y:
                dy = -1
            elif ey < y:
                dy = 1

    # Bound to -1, 0, 1
    if dx not in (-1, 0, 1):
        dx = 0
    if dy not in (-1, 0, 1):
        dy = 0

    return [dx, dy]

